import { useMemo } from 'react';
import { SketchPicker } from 'react-color';
import { Popover } from '@arco-design/web-react';
import styles from './index.module.less';

export interface EditorColorProps {
    value?: string;
    onChange?: (val: string) => void;
}
export default (props: EditorColorProps) => {


    const onChange = (color, ...arg) => {
        // 选择颜色判断是否存在透明度，如果存在在使用rgb表示，否则使用 #FFF 表示
        // console.log('onChangeComplete', color, ...arg)
        let value = color.hex;
        if(color.rgb.a !== 1){
            value = `rgba(${Object.values(color.rgb).join(',')})`
        }
        if(props.onChange){
            props.onChange(value);
        }
    }

    
    const value = useMemo(() => {
        if(!props.value) return;
        if(props.value.indexOf('rgb') === 0){
            const list =  props.value.replace(/rgba?|\(|\)/g,'').split(',')
            return {
                r: list[0],
                g: list[1],
                b: list[2],
                a: list[3],
            }
        }
        return props.value;
    },[props.value])

    return (
        <Popover
            position="br"
            trigger="click"
            content={
                <SketchPicker
                    color={value}
                    onChangeComplete={onChange}
                />
            }
        >
            {value? (
                <div className={styles['component']}>
                    <div className={styles['color']} 
                        style={{ backgroundColor: props.value }}
                    />
                    <div className={styles['colorText']}>
                        {props.value}
                    </div>
                </div>
            ): (
                <div className={styles.placeholder}>
                    选择颜色
                </div>
            )}
        </Popover>

    )
}